package com.integrydt.backend.controller;

import com.fasterxml.jackson.databind.ObjectMapper;import com.integrydt.backend.security.AuthenticatedUser;import com.integrydt.backend.service.AuditService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;

@RestController @RequestMapping("/api/v1/notifications")
public class NotificationsController {private final JdbcTemplate db;private final ObjectMapper json;private final AuditService audit;public NotificationsController(JdbcTemplate d,ObjectMapper j,AuditService a){db=d;json=j;audit=a;}public record SendRequest(String title,String body,String priority,List<String> deviceIds){}
 @PostMapping("/send") @PreAuthorize("hasAuthority('PERM_notifications.send')") @Transactional public ResponseEntity<?> send(@RequestBody SendRequest r,Authentication auth,HttpServletRequest req){AuthenticatedUser u=(AuthenticatedUser)auth.getPrincipal();String title=r.title()==null?null:r.title().trim(),body=r.body()==null?null:r.body().trim(),priority=r.priority()==null?null:r.priority().trim().toLowerCase();if(title==null||title.isBlank()||title.length()>200)return ResponseEntity.badRequest().body(Map.of("error","invalid_title"));if(body==null||body.isBlank()||body.length()>4000)return ResponseEntity.badRequest().body(Map.of("error","invalid_body"));if(!Set.of("low","normal","high","urgent").contains(priority))return ResponseEntity.badRequest().body(Map.of("error","invalid_priority"));List<String> ids=r.deviceIds()==null?List.of():r.deviceIds().stream().filter(x->x!=null&&!x.isBlank()).distinct().toList();if(ids.isEmpty()||ids.size()>50)return ResponseEntity.badRequest().body(Map.of("error","invalid_devices"));List<Map<String,Object>> devices=new ArrayList<>();for(String id:ids){var x=db.queryForList("SELECT CAST(id AS CHAR) id,name,status FROM devices WHERE company_id=? AND id=? AND status<>'revoked'",u.companyId(),id);if(x.isEmpty())return ResponseEntity.badRequest().body(Map.of("error","one_or_more_devices_not_available"));devices.add(x.get(0));}var defs=db.queryForList("SELECT CAST(t.id AS CHAR) toolId,CAST(g.id AS CHAR) gadgetId,CAST(gv.id AS CHAR) gadgetVersionId FROM company_tools ct JOIN tools t ON t.id=ct.tool_id AND t.enabled=1 JOIN gadgets g ON g.id=t.gadget_id AND g.enabled=1 JOIN company_gadget_policies cgp ON cgp.company_id=ct.company_id AND cgp.gadget_id=g.id AND cgp.enabled=1 JOIN gadget_versions gv ON gv.gadget_id=g.id AND gv.status='published' WHERE ct.company_id=? AND ct.enabled=1 AND t.code='desktop-notifications' AND gv.id=(SELECT gv2.id FROM gadget_versions gv2 WHERE gv2.gadget_id=g.id AND gv2.status='published' ORDER BY gv2.published_at DESC,gv2.created_at DESC LIMIT 1) LIMIT 1",u.companyId());if(defs.isEmpty())return ResponseEntity.status(409).body(Map.of("error","desktop_notifications_not_published"));var d=defs.get(0);List<Map<String,Object>> created=new ArrayList<>();for(var device:devices){String nid=UUID.randomUUID().toString(),jid=UUID.randomUUID().toString();String payload;try{payload=json.writeValueAsString(Map.of("notificationId",nid,"title",title,"body",body,"priority",priority));}catch(Exception e){throw new IllegalStateException(e);}db.update("INSERT INTO jobs(id,company_id,requested_by_user_id,device_id,tool_id,gadget_id,gadget_version_id,action,payload_json,status) VALUES(?,?,?,?,?,?,?,'show-notification',CAST(? AS JSON),'queued')",jid,u.companyId(),u.id(),device.get("id"),d.get("toolId"),d.get("gadgetId"),d.get("gadgetVersionId"),payload);db.update("INSERT INTO notifications(id,company_id,user_id,target_device_id,job_id,type,title,body,priority) VALUES(?,?,?,?,?,'desktop',?,?,?)",nid,u.companyId(),u.id(),device.get("id"),jid,title,body,priority);db.update("INSERT INTO job_events(job_id,event_type,message) VALUES(?,'queued','Desktop notification queued')",jid);audit.write(u.companyId(),u.id(),"notifications.send","notification",nid,"queued","web-api",req.getRemoteAddr(),Map.of("deviceId",device.get("id"),"jobId",jid,"priority",priority));created.add(Map.of("notificationId",nid,"jobId",jid,"deviceId",device.get("id"),"deviceName",device.get("name"),"status","queued"));}return ResponseEntity.accepted().body(Map.of("count",created.size(),"items",created));}
 @GetMapping("/sent") @PreAuthorize("hasAuthority('PERM_notifications.send')") public Object sent(@RequestParam(defaultValue="50") int limit,Authentication a){String c=((AuthenticatedUser)a.getPrincipal()).companyId();limit=Math.max(1,Math.min(200,limit));return db.queryForList("SELECT CAST(n.id AS CHAR) id,n.title,n.body,n.priority,n.created_at createdAt,CAST(n.target_device_id AS CHAR) deviceId,d.name deviceName,d.status deviceStatus,CAST(n.job_id AS CHAR) jobId,j.status deliveryStatus,j.started_at startedAt,j.finished_at finishedAt,r.stderr_text error FROM notifications n LEFT JOIN devices d ON d.id=n.target_device_id LEFT JOIN jobs j ON j.id=n.job_id LEFT JOIN job_results r ON r.job_id=n.job_id WHERE n.company_id=? AND n.type='desktop' ORDER BY n.created_at DESC LIMIT "+limit,c);}
}
